const C = {"P":{"origin":[300,239.78085307871007],"scale":1.1782358189133506,"azimuth":45,"elevation":30},"SV":[-36,-36],"DECK":64,"PAN_Z":46,"NOZ":[-32,-32],"NOZ_Z":78,"SY":[50,50],"SY_Z1":44,"TR_Z":47,"PL_DROP":9,"TIS_H":9,"TUM":[84,92],"SCREEN_OUT":[0,108],"BATCH":[[-14,6],[-4,12],[8,8],[12,-6],[-6,-4],[2,0]],"LAND":[[-12,12],[0,16],[14,10],[16,-4],[-4,2],[6,-12]],"LUMP_N":31,"TL":{"SLIDE":[0.2,0.7],"POUR":[0.8,2.2],"SHAKE":[2.3,3.4],"DRAIN":[3.4,4.6],"INJ":[4.8,5.8],"GROW":[6,8.6],"BACK":[8.8,9.4],"END":11.4}};
