    const i = Number(el.dataset.l);
    const o = s && !ab ? (i === 0 ? smooth(TL.INJ[1], TL.INJ[1] + 0.2, u) : Math.min(1, Math.max(0, grow * (C.LUMP_N - 1) - (i - 1)) * 2.5)) : 0;
